@Transactional
public void savePet(Pet pet) throws DataAccessException {
    pet.setType(findPetTypeById(pet.getType().getId()));
    petRepository.save(pet);
}

@Override
@Transactional
public void saveVisit(Visit visit) throws DataAccessException {
    visitRepository.save(visit);

}

@Override
@Transactional(readOnly = true)
public Collection<Vet> findVets() throws DataAccessException {
    return vetRepository.findAll();
}

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.isNew() && owner.getCustomerCode() == null) {
        long sequence = countOwnersInCity(owner.getCity()) + 1L;
        owner.setCustomerCode(
            customerCodeGenerator.generate(owner.getCity(), owner.getLastName(), sequence));
    }
    if (owner.isNew() && owner.getNamesakeCount() == null) {
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
    }
    if (owner.isNew() && owner.getMembershipNumber() == null) {
        owner.setMembershipNumber(
            membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
    }
    ownerRepository.save(owner);
}

/**
 * Count the owners already stored that share the given first and last name, compared
 * case-insensitively. Used to capture an owner's namesake count at creation time.
 */
/**
 * Count the owners already stored in the given city, compared case-insensitively. Used to
 * derive the per-city sequence embedded in a new owner's customer code.
 */
private long countOwnersInCity(String city) {
    return ownerRepository.findAll().stream()
        .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
        .count();
}

private int countNamesakes(String firstName, String lastName) {
    return (int) ownerRepository.findAll().stream()
        .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
            && equalsIgnoreCase(existing.getLastName(), lastName))
        .count();
}

private static boolean equalsIgnoreCase(String a, String b) {
    return a != null && a.equalsIgnoreCase(b);
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
    return ownerRepository.findByLastName(lastName);
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByTelephone(String telephone) throws DataAccessException {
    return ownerRepository.findByTelephone(telephone);
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnersInSameHousehold(String lastName, String address) throws DataAccessException {
    String targetLastName = householdNormalizer.normalize(lastName);
    String targetAddress = householdNormalizer.normalize(address);
    return ownerRepository.findAll().stream()
        .filter(owner -> householdNormalizer.normalize(owner.getLastName()).equals(targetLastName)
            && householdNormalizer.normalize(owner.getAddress()).equals(targetAddress))
        .toList();
}

@Override
@Transactional
public String joinHousehold(Owner owner) throws DataAccessException {
    Collection<Owner> members = findOwnersInSameHousehold(owner.getLastName(), owner.getAddress());
    if (members.isEmpty()) {
        return null;
    }
    String householdId = members.stream()
        .map(Owner::getHouseholdId)
        .filter(Objects::nonNull)
        .findFirst()
        .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
    for (Owner member : members) {
        if (!householdId.equals(member.getHouseholdId())) {
            member.setHouseholdId(householdId);
            ownerRepository.save(member);
        }
    }
    owner.setHouseholdId(householdId);
    return householdId;
}

@Override
@Transactional(readOnly = true)
public Collection<Visit> findVisitsByPetId(int petId) {
    return visitRepository.findByPetId(petId);
}

@Override
@Transactional(readOnly = true)
public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
    return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
}

